  .rail { grid-area: rail; position: sticky; top: 24px; }
  .headline { font-size: clamp(2.4rem, 4.6vw, 3.1rem); }
  .card--hero .card__main { grid-template-columns: 132px minmax(0, 1fr); }
  .card--hero { padding: 22px; }
