    margin-top: -8px;
    background: var(--ink);
    border-radius: 50% 46% 54% 48% / 56% 50% 50% 44%;
  }
  .toast { left: 44px; right: auto; margin: 0; width: 440px; bottom: 28px; }
}

@media (min-width: 1280px) {
  .sheet { padding: 26px 30px 30px; }
  .sheet__stage { height: 264px; }
}

