"""Temporary test driver: talks Marionette to a local headless Firefox. Not a deliverable."""
import socket, json, base64, subprocess, time, os, sys, shutil

ROOT = os.getcwd()
SHOTS = os.path.join(ROOT, '.shots')
TMP = os.path.join(os.environ.get('TMPDIR', '/tmp'), 'moss-mn')

class FF:
    def __init__(self, width, height, reduced=False, port=2828):
        prof = os.path.join(TMP, 'prof-%d' % port)
        shutil.rmtree(prof, ignore_errors=True); os.makedirs(prof)
        with open(os.path.join(prof, 'user.js'), 'w') as f:
            f.write('user_pref("marionette.port", %d);\n' % port)
            f.write('user_pref("ui.prefersReducedMotion", %d);\n' % (1 if reduced else 0))
            f.write('user_pref("network.proxy.type", 0);\n')
        self.p = subprocess.Popen(['firefox', '--headless', '--no-remote', '--profile', prof, '--marionette',
                                   '--window-size=%d,%d' % (width, height)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self.s = None
        for _ in range(100):
            try:
                self.s = socket.create_connection(('127.0.0.1', port), timeout=30); break
            except OSError:
                time.sleep(0.3)
        if not self.s: raise SystemExit('could not connect to marionette')
        self.buf = b''; self.id = 0
        self._read()
        self.cmd('WebDriver:NewSession', {})
        self.cmd('WebDriver:SetWindowRect', {'width': width, 'height': height})

    def _read(self):
        while b':' not in self.buf: self.buf += self.s.recv(65536)
        n, rest = self.buf.split(b':', 1); n = int(n)
        while len(rest) < n: rest += self.s.recv(1 << 20)
        self.buf = rest[n:]
        return json.loads(rest[:n])

    def cmd(self, name, params):
        self.id += 1
        m = json.dumps([0, self.id, name, params]).encode()
        self.s.sendall(str(len(m)).encode() + b':' + m)
        r = self._read()
        if r[2]: raise RuntimeError('%s: %s' % (name, r[2]))
        return r[3]

    def go(self, url): self.cmd('WebDriver:Navigate', {'url': url})
    def js(self, script, *args):
        return self.cmd('WebDriver:ExecuteScript', {'script': script, 'args': list(args)}).get('value')
    def key(self, *keys):
        special = {'Tab': '', 'Enter': '', 'Escape': '', 'Space': ' ', 'Shift': '', 'Control': ''}
        acts = []
        ks = [special.get(k, k) for k in keys]
        for k in ks: acts.append({'type': 'keyDown', 'value': k})
        for k in reversed(ks): acts.append({'type': 'keyUp', 'value': k})
        self.cmd('WebDriver:PerformActions', {'actions': [{'type': 'key', 'id': 'kb', 'actions': acts}]})
    def click(self, fk):
        self.js("const el=document.querySelector('[data-fk=\"'+arguments[0]+'\"]'); if(!el) throw new Error('missing '+arguments[0]); el.click();", fk)
    def shot(self, name, full=True):
        v = self.cmd('WebDriver:TakeScreenshot', {'full': full})['value']
        open(os.path.join(SHOTS, name + '.png'), 'wb').write(base64.b64decode(v))
    def focus(self):
        return self.js("const a=document.activeElement; return (a.dataset&&a.dataset.fk)||(a.tagName+'#'+a.id)")
    def live(self): return self.js("return document.getElementById('live').textContent")
    def quit(self):
        try: self.cmd('Marionette:Quit', {})
        except Exception: pass
        try: self.p.wait(timeout=10)
        except Exception: self.p.kill()

URL = 'file://' + ROOT + '/index.html'
EOF
