    print('toast after 8.5s:', ff.js("return document.getElementById('toast').hidden"))
    ff.click('reset'); time.sleep(0.6)
    print('reset -> cards:', ff.js("return [...document.querySelectorAll('#queue [data-card]')].map(e=>e.dataset.card)"))
